import React, { useState } from 'react'

const EMPTY = { year: '', branch: '', course: '' }

const YEARS = [
  { value: '1st', label: '1st' },
  { value: '2nd', label: '2nd' },
  { value: '3rd', label: '3rd' },
  { value: '4th', label: '4th' },
]

const COURSES = [
  { value: 'Polytechnic', label: 'Polytechnic', icon: 'fa-screwdriver-wrench' },
  { value: 'Btech', label: 'B.Tech', icon: 'fa-graduation-cap' },
  { value: 'MBA', label: 'MBA', icon: 'fa-briefcase' },
]

const BRANCHES = [
  { value: 'CSE', label: 'Computer Science', icon: 'fa-laptop-code' },
  { value: 'EC', label: 'Electronics & Comm.', icon: 'fa-tower-broadcast' },
  { value: 'ME', label: 'Mechanical', icon: 'fa-gears' },
  { value: 'CE', label: 'Civil', icon: 'fa-building' },
  { value: 'HR', label: 'Human Resources', icon: 'fa-users' },
  { value: 'Finance', label: 'Finance', icon: 'fa-chart-line' },
]

/* Section heading with a "done" tick once the group has a value */
const GroupTitle = ({ title, done }) => (
  <div className="mb-2.5 flex items-center gap-2">
    <h3 className="text-sm font-semibold text-slate-700 dark:text-slate-200">{title}</h3>
    {done && (
      <i
        className="fa-solid fa-circle-check text-xs text-emerald-600 dark:text-emerald-400"
        aria-label="selected"
      ></i>
    )}
  </div>
)

/* A selectable card: hidden radio + styled sibling (peer) */
const OptionCard = ({ name, option, checked, onChange }) => (
  <label className="relative block cursor-pointer">
    <input
      type="radio"
      name={name}
      value={option.value}
      checked={checked}
      onChange={onChange}
      className="peer sr-only"
    />
    <div
      className="flex items-center gap-3 rounded-xl border border-slate-200 bg-white p-3 transition
                 hover:border-indigo-300 hover:bg-indigo-50/60
                 peer-checked:border-indigo-600 peer-checked:bg-indigo-50 peer-checked:ring-1 peer-checked:ring-indigo-600
                 peer-checked:[&_.tile]:bg-indigo-600 peer-checked:[&_.tile]:text-white
                 peer-checked:[&_.chk]:scale-100 peer-checked:[&_.chk]:opacity-100
                 peer-focus-visible:ring-4 peer-focus-visible:ring-indigo-500/30
                 dark:border-slate-700 dark:bg-slate-900
                 dark:hover:border-indigo-400/50 dark:hover:bg-indigo-500/10
                 dark:peer-checked:border-indigo-400 dark:peer-checked:bg-indigo-500/15 dark:peer-checked:ring-indigo-400
                 dark:peer-checked:[&_.tile]:bg-indigo-400 dark:peer-checked:[&_.tile]:text-slate-900"
    >
      <span
        className="tile flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-slate-100 text-slate-500 transition-colors
                   dark:bg-slate-800 dark:text-slate-400"
      >
        <i className={`fa-solid ${option.icon}`} aria-hidden="true"></i>
      </span>
      <span className="min-w-0 flex-1">
        <span className="block truncate text-sm font-semibold text-slate-800 dark:text-slate-100">
          {option.label}
        </span>
        {option.value !== option.label && (
          <span className="block text-xs text-slate-500 dark:text-slate-400">{option.value}</span>
        )}
      </span>
      <i
        className="chk fa-solid fa-circle-check scale-50 text-indigo-600 opacity-0 transition dark:text-indigo-300"
        aria-hidden="true"
      ></i>
    </div>
  </label>
)

const Filters = ({ handelsubmit }) => {
  const [cred, setMycred] = useState(EMPTY)

  const handleChange = (e) => {
    setMycred({ ...cred, [e.target.name]: e.target.value })
  }

  const doneCount = [cred.year, cred.course, cred.branch].filter(Boolean).length
  // The backend route needs year, course and branch together
  const isComplete = doneCount === 3

  const handleSubmit = (event) => {
    event.preventDefault()
    if (!isComplete) return
    handelsubmit(cred)
  }

  const handelreset = (e) => {
    e.preventDefault()
    setMycred(EMPTY)
    handelsubmit(null) // null = show all records
  }

  const courseLabel = COURSES.find((c) => c.value === cred.course)?.label
  const branchLabel = BRANCHES.find((b) => b.value === cred.branch)?.label

  return (
    <form onSubmit={handleSubmit} onReset={handelreset} className="space-y-6">
      {/* Year: segmented control */}
      <fieldset>
        <legend className="sr-only">Year</legend>
        <GroupTitle title="Year" done={Boolean(cred.year)} />
        <div className="grid max-w-md grid-cols-4 gap-1 rounded-xl bg-slate-100 p-1 dark:bg-slate-800">
          {YEARS.map((y) => (
            <label key={y.value} className="relative cursor-pointer">
              <input
                type="radio"
                name="year"
                value={y.value}
                checked={cred.year === y.value}
                onChange={handleChange}
                className="peer sr-only"
              />
              <span
                className="block select-none rounded-lg py-2 text-center text-sm font-semibold text-slate-500 transition
                           hover:text-slate-800
                           peer-checked:bg-white peer-checked:text-indigo-600 peer-checked:shadow
                           peer-focus-visible:ring-4 peer-focus-visible:ring-indigo-500/30
                           dark:text-slate-400 dark:hover:text-slate-100
                           dark:peer-checked:bg-slate-700 dark:peer-checked:text-indigo-300"
              >
                {y.label}
              </span>
            </label>
          ))}
        </div>
      </fieldset>

      {/* Course: cards */}
      <fieldset>
        <legend className="sr-only">Course</legend>
        <GroupTitle title="Course" done={Boolean(cred.course)} />
        <div className="grid gap-2 sm:grid-cols-3">
          {COURSES.map((c) => (
            <OptionCard
              key={c.value}
              name="course"
              option={c}
              checked={cred.course === c.value}
              onChange={handleChange}
            />
          ))}
        </div>
      </fieldset>

      {/* Branch: cards */}
      <fieldset>
        <legend className="sr-only">Branch</legend>
        <GroupTitle title="Branch" done={Boolean(cred.branch)} />
        <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {BRANCHES.map((b) => (
            <OptionCard
              key={b.value}
              name="branch"
              option={b}
              checked={cred.branch === b.value}
              onChange={handleChange}
            />
          ))}
        </div>
      </fieldset>

      {/* Footer: summary + actions */}
      <div className="flex flex-wrap items-center gap-3 border-t border-slate-200 pt-4 dark:border-slate-700">
        <div className="mr-auto flex min-w-0 flex-wrap items-center gap-2 text-sm text-slate-500 dark:text-slate-400" aria-live="polite">
          {doneCount === 0 ? (
            <span>Select a year, course and branch.</span>
          ) : (
            <>
              <span className="font-medium">{doneCount} of 3 selected</span>
              {cred.year && (
                <span className="rounded-full bg-indigo-100 px-2.5 py-0.5 text-xs font-semibold text-indigo-700 dark:bg-indigo-500/20 dark:text-indigo-300">
                  {cred.year} year
                </span>
              )}
              {courseLabel && (
                <span className="rounded-full bg-indigo-100 px-2.5 py-0.5 text-xs font-semibold text-indigo-700 dark:bg-indigo-500/20 dark:text-indigo-300">
                  {courseLabel}
                </span>
              )}
              {branchLabel && (
                <span className="rounded-full bg-indigo-100 px-2.5 py-0.5 text-xs font-semibold text-indigo-700 dark:bg-indigo-500/20 dark:text-indigo-300">
                  {branchLabel}
                </span>
              )}
            </>
          )}
        </div>

        <button
          type="reset"
          className="h-10 rounded-lg border border-slate-200 px-4 text-sm font-semibold text-slate-600 transition-colors
                     hover:bg-slate-100 hover:text-slate-900 focus:outline-none focus-visible:ring-4 focus-visible:ring-indigo-500/30
                     dark:border-slate-700 dark:text-slate-400 dark:hover:bg-slate-800 dark:hover:text-slate-100"
        >
          Reset
        </button>
        <button
          type="submit"
          disabled={!isComplete}
          className="h-10 rounded-lg bg-indigo-600 px-5 text-sm font-semibold text-white transition-colors
                     hover:bg-indigo-700 focus:outline-none focus-visible:ring-4 focus-visible:ring-indigo-500/30
                     disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:bg-indigo-600
                     dark:bg-indigo-400 dark:text-slate-900 dark:hover:bg-indigo-300 dark:disabled:hover:bg-indigo-400"
        >
          Apply filters
        </button>
      </div>
    </form>
  )
}

export default Filters
